#!/usr/bin/env bats
# TDD: aggregate.sh reads normalized TSV records (file, testname, status, duration)
# on stdin and prints totals + flaky test list. Format chosen to be easy for
# report.sh to consume: lines prefixed with TOTAL_/FLAKY_ tags.

setup() {
  ROOT_DIR="$(cd "$(dirname "$BATS_TEST_FILENAME")/.." && pwd)"
  AGGREGATE="$ROOT_DIR/lib/aggregate.sh"
}

@test "aggregate computes passed/failed/skipped/duration totals" {
  run bash -c "printf 'a.xml\tt1\tpassed\t1.0\na.xml\tt2\tfailed\t2.0\na.xml\tt3\tskipped\t0.5\n' | '$AGGREGATE'"
  [ "$status" -eq 0 ]
  echo "$output" | grep -qE '^TOTAL_PASSED	1$'
  echo "$output" | grep -qE '^TOTAL_FAILED	1$'
  echo "$output" | grep -qE '^TOTAL_SKIPPED	1$'
  echo "$output" | grep -qE '^TOTAL_DURATION	3.5(0)?$'
}

@test "aggregate identifies a flaky test (passed in one file, failed in another)" {
  run bash -c "printf 'a.xml\tflaky\tpassed\t1.0\nb.xml\tflaky\tfailed\t1.0\n' | '$AGGREGATE'"
  [ "$status" -eq 0 ]
  echo "$output" | grep -qF "$(printf 'FLAKY\tflaky')"
}

@test "aggregate does not flag a consistently passing test as flaky" {
  run bash -c "printf 'a.xml\tstable\tpassed\t1.0\nb.xml\tstable\tpassed\t1.0\n' | '$AGGREGATE'"
  [ "$status" -eq 0 ]
  ! echo "$output" | grep -qF "$(printf 'FLAKY\tstable')"
}

@test "aggregate errors gracefully on empty input" {
  run bash -c "printf '' | '$AGGREGATE'"
  [ "$status" -ne 0 ]
}

#!/usr/bin/env bash
# Reads normalized TSV records (file, testname, status, duration) on stdin and
# prints machine-readable summary lines consumed by report.sh:
#   TOTAL_PASSED\t<n>   TOTAL_FAILED\t<n>   TOTAL_SKIPPED\t<n>   TOTAL_DURATION\t<n>
#   FLAKY\t<testname>   (one line per flaky test, sorted, deduped)
#
# Flaky definition: a test name that appears with status=passed in at least one
# input record AND status=failed in at least one (possibly different) input
# record. We key purely on test name (not file), since the same test run across
# matrix jobs is what we want to catch as inconsistent/flaky.

set -euo pipefail

die() {
  echo "aggregate: $*" >&2
  exit 1
}

main() {
  local input
  input="$(cat)"
  [ -n "$input" ] || die "no input records given (empty stdin)"

  awk -F'\t' '
    {
      status_count[$3]++
      duration_total += $4
      test_status[$2, $3] = 1
      if (!($2 in seen_tests)) { seen_tests[$2]=1; test_order[++n]=$2 }
    }
    END {
      printf "TOTAL_PASSED\t%d\n", status_count["passed"]+0
      printf "TOTAL_FAILED\t%d\n", status_count["failed"]+0
      printf "TOTAL_SKIPPED\t%d\n", status_count["skipped"]+0
      printf "TOTAL_DURATION\t%.2f\n", duration_total+0
      for (i=1; i<=n; i++) {
        t=test_order[i]
        if ((t,"passed") in test_status && (t,"failed") in test_status) {
          print "FLAKY\t" t
        }
      }
    }
  ' <<< "$input"
}

main "$@"

#!/usr/bin/env bats
# TDD: report.sh consumes aggregate.sh's TOTAL_*/FLAKY tagged lines on stdin and
# renders a GitHub-Actions-friendly Markdown summary.

setup() {
  ROOT_DIR="$(cd "$(dirname "$BATS_TEST_FILENAME")/.." && pwd)"
  REPORT="$ROOT_DIR/lib/report.sh"
}

@test "report renders a totals table with passed/failed/skipped/duration" {
  run bash -c "printf 'TOTAL_PASSED\t5\nTOTAL_FAILED\t2\nTOTAL_SKIPPED\t1\nTOTAL_DURATION\t3.50\n' | '$REPORT'"
  [ "$status" -eq 0 ]
  [[ "$output" == *"# Test Results Summary"* ]]
  [[ "$output" == *"| Passed | 5 |"* ]]
  [[ "$output" == *"| Failed | 2 |"* ]]
  [[ "$output" == *"| Skipped | 1 |"* ]]
  [[ "$output" == *"| Duration (s) | 3.50 |"* ]]
}

@test "report includes a flaky-tests section listing each flaky test" {
  run bash -c "printf 'TOTAL_PASSED\t1\nTOTAL_FAILED\t1\nTOTAL_SKIPPED\t0\nTOTAL_DURATION\t1.00\nFLAKY\ttest_network_timeout\n' | '$REPORT'"
  [ "$status" -eq 0 ]
  [[ "$output" == *"## Flaky Tests"* ]]
  [[ "$output" == *"test_network_timeout"* ]]
}

@test "report notes when there are no flaky tests" {
  run bash -c "printf 'TOTAL_PASSED\t1\nTOTAL_FAILED\t0\nTOTAL_SKIPPED\t0\nTOTAL_DURATION\t1.00\n' | '$REPORT'"
  [ "$status" -eq 0 ]
  [[ "$output" == *"No flaky tests detected"* ]]
}

#!/usr/bin/env bats
# TDD: end-to-end test of bin/aggregate-results.sh against the matrix fixtures,
# which contain a deliberately flaky test (test_network_timeout: pass, pass, fail).

setup() {
  ROOT_DIR="$(cd "$(dirname "$BATS_TEST_FILENAME")/.." && pwd)"
  MAIN="$ROOT_DIR/bin/aggregate-results.sh"
  FIXTURES="$ROOT_DIR/fixtures"
}

@test "main script auto-detects format by extension and aggregates matrix fixtures" {
  run "$MAIN" "$FIXTURES/matrix/ubuntu.xml" "$FIXTURES/matrix/macos.xml" "$FIXTURES/matrix/windows.json"
  [ "$status" -eq 0 ]
  [[ "$output" == *"# Test Results Summary"* ]]
  [[ "$output" == *"| Passed | 5 |"* ]]
  [[ "$output" == *"| Failed | 1 |"* ]]
  [[ "$output" == *"| Skipped | 0 |"* ]]
  [[ "$output" == *"test_network_timeout"* ]]
}

@test "main script writes to GITHUB_STEP_SUMMARY when set" {
  local summary_file="$BATS_TEST_TMPDIR/summary.md"
  GITHUB_STEP_SUMMARY="$summary_file" run "$MAIN" "$FIXTURES/junit_sample.xml"
  [ "$status" -eq 0 ]
  [ -f "$summary_file" ]
  grep -q "# Test Results Summary" "$summary_file"
}

@test "main script errors out with meaningful message when no args given" {
  run "$MAIN"
  [ "$status" -ne 0 ]
  [[ "$output" == *"usage"* ]] || [[ "$output" == *"no input files"* ]]
}

@test "main script errors out when a given file does not exist" {
  run "$MAIN" "$FIXTURES/nope.xml"
  [ "$status" -ne 0 ]
  [[ "$output" == *"not found"* ]]
}

@test "main script rejects unrecognized file extensions" {
  run "$MAIN" "$FIXTURES/json_sample.json.bak"
  [ "$status" -ne 0 ]
}
